const n=new Intl.NumberFormat("vi-VN");function e(t){return t==null?"—":n.format(Math.round(t))+"đ"}function i(t){if(!t)return"—";const r=new Date(t);return isNaN(r.getTime())?t:r.toLocaleDateString("vi-VN",{year:"numeric",month:"2-digit",day:"2-digit"})}function o(t){if(!t)return"—";const r=new Date(t.includes(" ")?t.replace(" ","T"):t);return isNaN(r.getTime())?t:r.toLocaleString("vi-VN",{dateStyle:"short",timeStyle:"short"})}export{i as a,o as b,e as f};
